<?php /** Draft a credit note / edit its lines (screens `credit-note-add`, `credit-note-edit`). Data: c (null when new), taxRates, invoice, clients, here, notice */
$editing = $c !== null; $cid = $editing ? (int) $c['credit_note_id'] : 0; $cur = $editing ? $c['currency'] : ($invoice['currency'] ?? ''); ?>
<?= view('shared/header.php', ['id' => 'credit-note-form', 'title' => $editing ? 'Edit the draft credit note' : 'Draft a credit note', 'crumbs' => [['Home', '/'], ['Credit notes', '/credit-notes/'], [$editing ? 'Draft #' . $cid : 'Draft', null]],
    'back' => back_link() ?? ($invoice !== null ? ['/invoices/' . (int) $invoice['invoice_id'], 'the invoice'] : ['/credit-notes/', 'credit notes']), 'action' => $editing ? hx_link('/credit-notes/' . $cid, 'Done', 'btn btn-primary btn-touch', 'id="credit-note-form-done-btn"') : '']) ?>
<div class="main-content" id="credit-note-form-content">
    <?= view('shared/notice.php', ['notice' => $notice]) ?>
    <form method="post" action="/credit-notes/save.php" hx-post="/credit-notes/save.php" hx-target="#flash" class="card mb-3" id="credit-note-head-form"><div class="card-body"><div class="row g-3">
        <?= csrf_field() ?><?php if ($editing): ?><input type="hidden" name="credit_note" value="<?= $cid ?>"><?php endif; ?>
        <?php if (!$editing): ?>
            <?php if ($invoice !== null): ?><input type="hidden" name="invoice" value="<?= (int) $invoice['invoice_id'] ?>"><div class="col-12 fs-12" id="credit-note-form-invoice">Against invoice <strong><?= e((string) $invoice['number']) ?></strong> — <?= e($invoice['client_name']) ?> · <?= e(fmt_money($invoice['total'], $invoice['currency'])) ?> (owed <?= e(fmt_money($invoice['balance_due'], $invoice['currency'])) ?>). Its client, engagement and currency come with it.</div>
            <?php else: ?><div class="col-12"><label class="form-label" id="credit-note-form-field-client-label" for="credit-note-form-field-client-open">Client</label><?= picker_field(['id' => 'credit-note-form-field-client', 'labelledby' => 'credit-note-form-field-client-label', 'name' => 'client', 'source' => 'client', 'value' => null, 'required' => true, 'placeholder' => 'Choose the client']) ?><div class="form-text">Or start from the invoice it corrects — Credit this invoice, on the invoice.</div></div><?php endif; ?>
        <?php else: ?><div class="col-12 fs-12" id="credit-note-form-for"><?= e($c['client_name']) ?><?= $c['invoice_number'] ? ' · for ' . e($c['invoice_number']) : '' ?> · <?= e($cur) ?></div><?php endif; ?>
        <div class="col-12 col-md-8"><label class="form-label" for="credit-note-form-field-reason">Reason</label><input type="text" name="reason" id="credit-note-form-field-reason" class="form-control btn-touch" maxlength="1000" value="<?= e((string) ($c['reason'] ?? '')) ?>" placeholder="What is being corrected"></div>
        <div class="col-12 col-md-4"><label class="form-label" for="credit-note-form-field-date">Issue date</label><input type="date" name="issue_date" id="credit-note-form-field-date" class="form-control btn-touch" value="<?= e((string) ($c['issue_date'] ?? date('Y-m-d'))) ?>"></div>
        <div class="col-12 d-grid d-md-flex gap-2"><button type="submit" class="btn btn-primary btn-touch" id="credit-note-form-save-btn"><?= $editing ? 'Save' : 'Draft the credit note' ?></button></div>
    </div></div></form>
    <?php if ($editing): ?>
    <div class="card mb-3" id="credit-note-lines"><div class="card-header"><h5 class="card-title mb-0">Lines</h5></div>
        <?php if ($c['lines'] === []): ?><div class="card-body text-muted" id="credit-note-lines-empty">No line yet: add what is being credited.</div><?php else: ?>
        <div class="table-responsive"><table class="table mb-0 fs-12" id="credit-note-lines-table"><thead><tr><th>What</th><th class="text-end">Qty</th><th class="text-end">Price</th><th class="text-end">Tax</th><th class="text-end">Total</th><th></th></tr></thead><tbody>
        <?php foreach ($c['lines'] as $l): $lid = (int) $l['line_id']; ?><tr id="credit-line-<?= $lid ?>"><td><?= e($l['description']) ?></td><td class="text-end"><?= e(rtrim(rtrim((string) $l['quantity'], '0'), '.')) ?></td><?= fmt_money_cell($l['unit_price'], $cur) ?><td class="text-end"><?= (float) $l['tax_rate'] > 0 ? e(days_label($l['tax_rate'])) . '%' : '—' ?></td><?= fmt_money_cell($l['line_total'], $cur, 'credit-line-' . $lid . '-total') ?>
            <td class="text-end"><form method="post" action="/credit-notes/lines/save.php" hx-post="/credit-notes/lines/save.php" hx-target="#flash" hx-confirm="Remove this line?" class="d-inline"><?= csrf_field() ?><input type="hidden" name="credit_note" value="<?= $cid ?>"><input type="hidden" name="line" value="<?= $lid ?>"><input type="hidden" name="remove" value="yes"><input type="hidden" name="return_to" value="<?= e($here) ?>"><button type="submit" class="btn btn-sm btn-light text-danger" id="credit-line-<?= $lid ?>-remove-btn">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </div>
    <div class="card mb-3" id="credit-note-totals"><div class="card-body p-3 d-flex flex-wrap justify-content-between gap-2 fs-12"><span>Subtotal <strong id="credit-total-subtotal"><?= e(fmt_money($c['subtotal'], $cur)) ?></strong></span><span>Tax <strong id="credit-total-tax"><?= e(fmt_money($c['tax_total'], $cur)) ?></strong></span><span>Credit <strong id="credit-total-total"><?= e(fmt_money($c['total'], $cur)) ?></strong></span></div></div>
    <div class="card mb-3" id="credit-note-add-line"><div class="card-header"><h5 class="card-title mb-0">Add a line</h5></div><div class="card-body">
        <form method="post" action="/credit-notes/lines/save.php" hx-post="/credit-notes/lines/save.php" hx-target="#flash" class="row g-2" id="credit-line-form"><?= csrf_field() ?><input type="hidden" name="credit_note" value="<?= $cid ?>"><input type="hidden" name="return_to" value="<?= e($here) ?>">
            <div class="col-12"><label class="form-label fs-12 text-muted" for="credit-line-field-description">What is credited</label><input type="text" name="description" id="credit-line-field-description" class="form-control btn-touch" maxlength="500" required></div>
            <div class="col-4"><label class="form-label fs-12 text-muted" for="credit-line-field-quantity">Quantity</label><input type="number" step="0.0001" min="0.0001" name="quantity" id="credit-line-field-quantity" class="form-control btn-touch" value="1"></div>
            <div class="col-4"><label class="form-label fs-12 text-muted" for="credit-line-field-price">Price (<?= e($cur) ?>)</label><input type="text" inputmode="decimal" name="unit_price" id="credit-line-field-price" class="form-control btn-touch" required></div>
            <div class="col-4"><label class="form-label fs-12 text-muted" for="credit-line-field-tax">Tax</label><select name="tax_rate" id="credit-line-field-tax" class="form-select btn-touch"><option value="">No tax</option><?php foreach ($taxRates as $t): ?><option value="<?= (int) $t['tax_rate_id'] ?>"><?= e($t['name']) ?> (<?= e(days_label($t['rate'])) ?>%)</option><?php endforeach; ?></select></div>
            <div class="col-12 d-grid"><button type="submit" class="btn btn-light btn-touch" id="credit-line-save-btn">Add the line</button></div>
        </form></div></div>
    <form method="post" action="/credit-notes/delete.php" hx-post="/credit-notes/delete.php" hx-target="#flash" hx-confirm="Delete this draft credit note?"><?= csrf_field() ?><input type="hidden" name="credit_note" value="<?= $cid ?>"><button type="submit" class="btn btn-light btn-touch text-danger" id="credit-note-delete-btn">Delete the draft</button></form>
    <?php endif; ?>
</div>
